// Push send gate. Called right before a push is handed to the provider.
// State is in memory only; a restart forgets all counts.
//
// Rule order (first failing rule is reported):
//   1. quiet-hours  marketing only; customer's own local DND window
//   2. daily-cap    marketing only; max 3 sent per customer-local calendar day
// Transactional pushes always pass. Only sent pushes are counted.

const DAILY_MARKETING_CAP = 3;
const CATEGORIES = new Set(['marketing', 'transactional']);
const HHMM = /^([01]\d|2[0-3]):([0-5]\d)$/;

// userId -> { day: 'YYYY-MM-DD' (customer-local), marketing: number, transactional: number }
const sentByUser = new Map();
// timezone -> Intl.DateTimeFormat
const formatters = new Map();

function formatterFor(timezone) {
  let formatter = formatters.get(timezone);
  if (!formatter) {
    try {
      formatter = new Intl.DateTimeFormat('en-CA', {
        timeZone: timezone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        hourCycle: 'h23',
      });
    } catch {
      throw new TypeError(`invalid IANA timezone: ${timezone}`);
    }
    formatters.set(timezone, formatter);
  }
  return formatter;
}

// Returns the customer's local calendar day and minute-of-day for an instant.
function localClock(now, timezone) {
  const parts = {};
  for (const part of formatterFor(timezone).formatToParts(now)) {
    parts[part.type] = part.value;
  }
  return {
    day: `${parts.year}-${parts.month}-${parts.day}`,
    minutes: Number(parts.hour) * 60 + Number(parts.minute),
  };
}

function toMinutes(value, name) {
  const match = typeof value === 'string' ? HHMM.exec(value) : null;
  if (!match) {
    throw new TypeError(`${name} must be "HH:MM" 24-hour time, got: ${value}`);
  }
  return Number(match[1]) * 60 + Number(match[2]);
}

// Window [start, end). Wraps past midnight when start > end.
// start === end means no quiet window.
function inQuietWindow(minutes, start, end) {
  if (start === end) return false;
  if (start < end) return minutes >= start && minutes < end;
  return minutes >= start || minutes < end;
}

function validate(candidate, now) {
  if (candidate === null || typeof candidate !== 'object') {
    throw new TypeError('candidate must be an object');
  }
  const { userId, category, timezone, quietStart, quietEnd } = candidate;
  if (typeof userId !== 'string' || userId === '') {
    throw new TypeError('userId must be a non-empty string');
  }
  if (!CATEGORIES.has(category)) {
    throw new TypeError(`category must be "marketing" or "transactional", got: ${category}`);
  }
  if (typeof timezone !== 'string') {
    throw new TypeError('timezone must be an IANA time zone string');
  }
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('now must be a valid Date');
  }
  return {
    userId,
    category,
    timezone,
    quietStart: toMinutes(quietStart, 'quietStart'),
    quietEnd: toMinutes(quietEnd, 'quietEnd'),
  };
}

export function decide(candidate, now) {
  const c = validate(candidate, now);
  const { day, minutes } = localClock(now, c.timezone);

  // Transactional pushes (e.g. courier nearby, security code) bypass quiet hours and the cap.
  if (c.category === 'marketing') {
    if (inQuietWindow(minutes, c.quietStart, c.quietEnd)) {
      return { send: false, rule: 'quiet-hours' };
    }
  }

  let counts = sentByUser.get(c.userId);
  if (!counts || counts.day !== day) {
    counts = { day, marketing: 0, transactional: 0 };
    sentByUser.set(c.userId, counts);
  }

  if (c.category === 'marketing' && counts.marketing >= DAILY_MARKETING_CAP) {
    return { send: false, rule: 'daily-cap' };
  }

  counts[c.category] += 1;
  return { send: true, rule: null };
}

import assert from 'node:assert/strict';
import { decide } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g2-1/bot.mjs';

const IST = 'Europe/Istanbul'; // UTC+3, no DST
const mk = (userId, category, extra = {}) => ({
  userId, category, timezone: IST, quietStart: '22:00', quietEnd: '07:30', ...extra,
});
const at = (iso) => new Date(iso);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log('ok -', name); };

ok('marketing: first 3 sent, 4th blocked by daily-cap', () => {
  const t = at('2026-10-23T10:00:00Z'); // 13:00 local
  for (let i = 0; i < 3; i++) assert.deepEqual(decide(mk('a', 'marketing'), t), { send: true, rule: null });
  assert.deepEqual(decide(mk('a', 'marketing'), t), { send: false, rule: 'daily-cap' });
});

ok('transactional always sent, even past marketing cap', () => {
  const t = at('2026-10-23T10:05:00Z');
  for (let i = 0; i < 5; i++) assert.deepEqual(decide(mk('a', 'transactional'), t), { send: true, rule: null });
});

ok('transactional bypasses quiet hours', () => {
  const t = at('2026-10-23T20:00:00Z'); // 23:00 local, inside window
  assert.deepEqual(decide(mk('q', 'transactional'), t), { send: true, rule: null });
});

ok('marketing in quiet window (wrapping) blocked with quiet-hours', () => {
  assert.deepEqual(decide(mk('q', 'marketing'), at('2026-10-23T20:00:00Z')), { send: false, rule: 'quiet-hours' }); // 23:00
  assert.deepEqual(decide(mk('q', 'marketing'), at('2026-10-23T04:00:00Z')), { send: false, rule: 'quiet-hours' }); // 07:00
});

ok('boundaries: start inclusive, end exclusive', () => {
  // 22:00 local = 19:00Z -> inside
  assert.equal(decide(mk('b1', 'marketing'), at('2026-10-23T19:00:00Z')).rule, 'quiet-hours');
  // 07:30 local = 04:30Z -> outside
  assert.deepEqual(decide(mk('b2', 'marketing'), at('2026-10-23T04:30:00Z')), { send: true, rule: null });
  // 21:59 local = 18:59Z -> outside
  assert.deepEqual(decide(mk('b3', 'marketing'), at('2026-10-23T18:59:00Z')), { send: true, rule: null });
});

ok('quiet-hours blocks do not count toward the cap', () => {
  const quiet = at('2026-10-23T20:00:00Z'); // 23:00 local
  for (let i = 0; i < 10; i++) decide(mk('nc', 'marketing'), quiet);
  const day = at('2026-10-23T10:00:00Z');
  for (let i = 0; i < 3; i++) assert.equal(decide(mk('nc', 'marketing'), day).send, true);
  assert.equal(decide(mk('nc', 'marketing'), day).rule, 'daily-cap');
});

ok('non-wrapping window', () => {
  const c = { userId: 'nw', category: 'marketing', timezone: IST, quietStart: '13:00', quietEnd: '14:00' };
  assert.equal(decide(c, at('2026-10-23T10:30:00Z')).rule, 'quiet-hours'); // 13:30 local
  assert.equal(decide(c, at('2026-10-23T11:00:00Z')).send, true); // 14:00 local
});

ok('equal start/end means no quiet window', () => {
  const c = { userId: 'eq', category: 'marketing', timezone: IST, quietStart: '09:00', quietEnd: '09:00' };
  assert.equal(decide(c, at('2026-10-23T06:00:00Z')).send, true); // 09:00 local
});

ok('cap resets at customer-local midnight, not UTC midnight', () => {
  // 2026-10-23 22:30 local (Istanbul) = 19:30Z, still Oct 23 local
  const late = at('2026-10-23T19:30:00Z');
  for (let i = 0; i < 3; i++) decide(mk('dy', 'marketing', { quietStart: '00:00', quietEnd: '00:00' }), late);
  assert.equal(decide(mk('dy', 'marketing', { quietStart: '00:00', quietEnd: '00:00' }), late).rule, 'daily-cap');
  // 00:30 local Oct 24 = 21:30Z Oct 23 -> new local day, cap reset
  const next = at('2026-10-23T21:30:00Z');
  assert.deepEqual(decide(mk('dy', 'marketing', { quietStart: '00:00', quietEnd: '00:00' }), next), { send: true, rule: null });
});

ok('server UTC is ignored: customer in Auckland uses its own day', () => {
  const c = (id) => ({ userId: id, category: 'marketing', timezone: 'Pacific/Auckland', quietStart: '00:00', quietEnd: '00:00' });
  // 2026-10-23T12:00Z = 2026-10-24 01:00 Auckland (NZDT, UTC+13)
  const t = at('2026-10-23T12:00:00Z');
  for (let i = 0; i < 3; i++) decide(c('nz'), t);
  assert.equal(decide(c('nz'), t).rule, 'daily-cap');
  // 2026-10-24T00:00Z = 13:00 Auckland Oct 24 -> still same local day as 12:00Z? No: Oct 24 local, so new day
  assert.deepEqual(decide(c('nz'), at('2026-10-24T00:00:00Z')), { send: true, rule: null });
});

ok('users are counted independently', () => {
  const t = at('2026-10-23T10:00:00Z');
  for (let i = 0; i < 3; i++) decide(mk('u1', 'marketing'), t);
  assert.equal(decide(mk('u1', 'marketing'), t).rule, 'daily-cap');
  assert.equal(decide(mk('u2', 'marketing'), t).send, true);
});

ok('invalid input throws', () => {
  const t = at('2026-10-23T10:00:00Z');
  assert.throws(() => decide(mk('x', 'promo'), t), TypeError);
  assert.throws(() => decide(mk('x', 'marketing', { timezone: 'Mars/Olympus' }), t), TypeError);
  assert.throws(() => decide(mk('x', 'marketing', { quietStart: '25:00' }), t), TypeError);
  assert.throws(() => decide(mk('x', 'marketing', { quietEnd: '7:30' }), t), TypeError);
  assert.throws(() => decide(mk('x', 'marketing'), new Date('nope')), TypeError);
  assert.throws(() => decide(mk('', 'marketing'), t), TypeError);
});

console.log(`\n${n} tests passed`);

